        public async Task<ActionResult<TodoList>> GetTodoList(long id)
        {
            var todoList = await _todoListsService.GetTodoListAsync(id);

            if (todoList == null)
            {
                return NotFound();
            }

            return Ok(todoList);
        }

        // PUT: api/todolists/5
