    if ($lines.Count -eq 0) { continue }
    $valid = $lines.Count
    $covered = @($lines | Where-Object { [int]$_.hits -gt 0 }).Count
    $folder = if ($filename -match '^(TodoApi|ExternalApi)\\([^\\]+)') { "$($matches[1])/$($matches[2])" } elseif ($filename -match '^(TodoApi|ExternalApi)\\') { $matches[1] } else { '(other)' }
    [pscustomobject]@{ Folder=$folder; File=$filename; Valid=$valid; Covered=$covered }
}
$rows | Group-Object Folder | ForEach-Object {
    $valid = ($_.Group | Measure-Object Valid -Sum).Sum
    $covered = ($_.Group | Measure-Object Covered -Sum).Sum
    [pscustomobject]@{ Component=$_.Name; Lines=$valid; Covered=$covered; Coverage=('{0:N2}%' -f (($covered / [Math]::Max($valid,1))*100)) }
} | Sort-Object Component | Format-Table -AutoSize
"`nExcluding migrations:"
$filtered = $rows | Where-Object { $_.Folder -ne 'TodoApi/Migrations' }
$valid = ($filtered | Measure-Object Valid -Sum).Sum
$covered = ($filtered | Measure-Object Covered -Sum).Sum
"Line coverage excluding migrations: {0:N2}% ({1}/{2})" -f (($covered / $valid) * 100), $covered, $valid

